/* The Odds API (api.the-odds-api.com) key lives in the "Odds API key" field
   (LS.key). The one-tap pull and the NFL/CFB live-odds fetchers were reading
   LS.oddspapi — the oddspapi.io field, a different company — and sending that
   to the-odds-api.com. Everything that calls the-odds-api.com resolves here.
   Falls back to the oddspapi field in case the key was pasted there. */
function theOddsApiKey(){return get(LS.key,'')||get(LS.oddspapi,'')}

/* ═══════════════════════════════════════════════════════════════════════════
   INTAKE — one door for book odds, trends, predicted scores and consensus.
   Order of preference, cheapest and most reliable first:
     1. Local parse of pasted/typed/txt/docx text — free, instant, offline.
        Understands TheDesk grammar AND raw copy-paste off a sportsbook board.
     2. Gemini as a TRANSCRIBER only — it rewrites a screenshot/PDF (or text
        the local parser couldn't read) into TheDesk grammar, which the same
        local parser then reads. No JSON, so no "couldn't parse a clean list".
   Screenshots are downscaled before upload, sent one per request, two at a
   time, each with a hard 45s timeout, a 3-attempt budget and a Cancel button.
   One bad image never sinks the batch. Nothing saves until you confirm.
   ═══════════════════════════════════════════════════════════════════════════ */
const INTAKE={busy:false,ctl:null,result:null};
const INTAKE_BUILD='intake 2026-09-26y';
/* Stamp the card so it's obvious which code the phone is actually running. */
setTimeout(()=>{try{const t=document.getElementById('intakeType'),sr=document.getElementById('intakeSource');if(t)t.value=localStorage.getItem('d4.intakeType')||'auto';if(sr)sr.value=localStorage.getItem('d4.intakeSource')||'';}catch(e){}},0);
setTimeout(()=>{try{const b=document.getElementById('intakeCancelBtn');if(b&&!document.getElementById('intakeBuild')){
  const d=document.createElement('div');d.id='intakeBuild';d.className='sub mono';d.style.cssText='font-size:9.5px;opacity:.6;margin-top:4px';
  d.textContent=INTAKE_BUILD+' · reads key:value, grammar & board copy locally';b.parentNode.after(d);}}catch(e){}},0);
const INTAKE_NFL={ARI:'cardinals arizona',ATL:'falcons atlanta',BAL:'ravens baltimore',BUF:'bills buffalo',CAR:'panthers carolina',
 CHI:'bears chicago',CIN:'bengals cincinnati',CLE:'browns cleveland',DAL:'cowboys dallas',DEN:'broncos denver',DET:'lions detroit',
 GB:'packers green bay',HOU:'texans houston',IND:'colts indianapolis',JAX:'jaguars jacksonville',KC:'chiefs kansas city',
 LV:'raiders las vegas',LAC:'chargers',LAR:'rams',MIA:'dolphins miami',MIN:'vikings minnesota',NE:'patriots new england',
 NO:'saints new orleans',NYG:'giants',NYJ:'jets',PHI:'eagles philadelphia',PIT:'steelers pittsburgh',SF:'49ers niners san francisco',
 SEA:'seahawks seattle',TB:'buccaneers bucs tampa bay',TEN:'titans tennessee',WSH:'commanders washington'};
const INTAKE_NFL_ALIAS={WAS:'WSH',JAC:'JAX',LA:'LAR',OAK:'LV',SD:'LAC',STL:'LAR',GNB:'GB',KAN:'KC',NWE:'NE',NOR:'NO',SFO:'SF',TAM:'TB'};
function intakeNFLAbbr(raw){
  const t=String(raw||'').trim();if(!t)return null;
  if(typeof nflAbbrFor==='function'){const a=nflAbbrFor(t);if(a)return a;}
  const U=t.toUpperCase();if(INTAKE_NFL[U])return U;if(INTAKE_NFL_ALIAS[U])return INTAKE_NFL_ALIAS[U];
  const l=t.toLowerCase().replace(/[^a-z0-9 ]/g,' ');
  const nick=Object.keys(INTAKE_NFL).find(k=>INTAKE_NFL[k].split(' ')[0]&&new RegExp('\\b'+INTAKE_NFL[k].split(' ')[0]+'\\b').test(l));
  if(nick)return nick;
  return Object.keys(INTAKE_NFL).find(k=>INTAKE_NFL[k].split(' ').slice(1).join(' ')&&l.includes(INTAKE_NFL[k].split(' ').slice(1).join(' ')))||null;
}
const INTAKE_NHL={ANA:'anaheim ducks',BOS:'boston bruins',BUF:'buffalo sabres',CGY:'calgary flames',CAR:'carolina hurricanes',CHI:'chicago blackhawks',
 COL:'colorado avalanche',CBJ:'columbus blue jackets',DAL:'dallas stars',DET:'detroit red wings',EDM:'edmonton oilers',FLA:'florida panthers',LA:'los angeles kings',
 MIN:'minnesota wild',MTL:'montreal canadiens',NSH:'nashville predators',NJ:'new jersey devils',NYI:'new york islanders',NYR:'new york rangers',OTT:'ottawa senators',
 PHI:'philadelphia flyers',PIT:'pittsburgh penguins',SJ:'san jose sharks',SEA:'seattle kraken',STL:'st louis blues',TB:'tampa bay lightning',TOR:'toronto maple leafs',
 UTAH:'utah mammoth',VAN:'vancouver canucks',VGK:'vegas golden knights',WSH:'washington capitals',WPG:'winnipeg jets'};
const INTAKE_NHL_ALIAS={LAK:'LA',NJD:'NJ',SJS:'SJ',TBL:'TB',VEG:'VGK',LV:'VGK',UTA:'UTAH',UHC:'UTAH',ARI:'UTAH',WAS:'WSH',MON:'MTL',CLB:'CBJ',NAS:'NSH',WIN:'WPG'};
function intakeNHLAbbr(raw){
  const t=String(raw||'').trim();if(!t)return null;
  if(typeof nhlAbbrFor==='function'){const a=nhlAbbrFor(t);if(a)return a;}
  const U=t.toUpperCase().replace(/[^A-Z]/g,'');if(INTAKE_NHL[U])return U;if(INTAKE_NHL_ALIAS[U])return INTAKE_NHL_ALIAS[U];
  const l=' '+t.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9 ]/g,' ').replace(/\s+/g,' ')+' ';
  const nicks=Object.entries(INTAKE_NHL).map(([k,v])=>{const w=v.split(' ');const nick=(k==='CBJ'?'blue jackets':k==='DET'?'red wings':k==='TOR'?'maple leafs':k==='VGK'?'golden knights':w[w.length-1]);return[k,nick];}).sort((a,b)=>b[1].length-a[1].length);
  for(const [k,n] of nicks)if(l.includes(' '+n+' '))return k;
  const cities=Object.entries(INTAKE_NHL).filter(([k])=>k!=='NYI'&&k!=='NYR').map(([k,v])=>[k,v.replace(/ (ducks|bruins|sabres|flames|hurricanes|blackhawks|avalanche|blue jackets|stars|red wings|oilers|panthers|kings|wild|canadiens|predators|devils|senators|flyers|penguins|sharks|kraken|blues|lightning|maple leafs|mammoth|canucks|golden knights|capitals|jets)$/,'')]).sort((a,b)=>b[1].length-a[1].length);
  for(const [k,c] of cities)if(l.includes(' '+c+' '))return k;
  return null;
}
