      if(res.propSkipped)parts.push(`${res.propSkipped} player-prop line${res.propSkipped>1?'s':''} not recognized`);
      if(res.skipped.length)parts.push(`${res.skipped.length} line${res.skipped.length>1?'s':''} unrecognized`);
