/* on-device speed log: every tab switch is timed so a slow screen on the phone
   shows up in Settings → Storage with real numbers, not guesses */
const PERF_LOG=[];
function perfNote(what,ms){PERF_LOG.push({what,ms:Math.round(ms),at:Date.now()});if(PERF_LOG.length>30)PERF_LOG.shift();}
if(typeof window!=='undefined')window.addEventListener('load',()=>{try{const nav=performance.getEntriesByType('navigation')[0];perfNote('page load',nav?nav.loadEventEnd:performance.now());}catch(e){}});
function tab(n,b){const _t0=performance.now();try{return tabRaw(n,b);}finally{perfNote('tab: '+n,performance.now()-_t0);}}
function tabRaw(n,b){
  document.querySelectorAll('.view').forEach(v=>v.classList.remove('on'));
  document.getElementById('v-'+n).classList.add('on');
  document.querySelectorAll('nav>button').forEach(x=>x.classList.remove('on'));
  if(b)b.classList.add('on');
  if(n==='games'&&ACTIVE_SPORT==='nfl')renderNFL();
  if(n==='games'&&ACTIVE_SPORT==='ncaaf')renderNCAAF();
  if(n==='games'&&ACTIVE_SPORT==='nhl'&&typeof renderNHL==='function')renderNHL();
  if(n==='games'&&ACTIVE_SPORT==='nba'&&typeof renderNBA==='function')renderNBA();
  if(n==='games'&&ACTIVE_SPORT==='ncaab'&&typeof renderNCAAB==='function')renderNCAAB();
  if(n==='tickets'){ticketsDefaultTab();renderTickets();btAutoOnce();try{const tv=document.getElementById('v-tickets');if(tv&&!document.getElementById('btStatus')&&btUngraded().length){const d=document.createElement('div');d.innerHTML=btBarHtml();tv.insertBefore(d,tv.firstChild);}}catch(e){}}
  if(n==='grades')renderGrades(true);
  if(n==='recap')renderRecap();
  if(n==='best'){bestTab(BESTTAB||'today');}
  if(n==='settings')fillSettingsTab();
  if(n==='settings'){const m=document.getElementById('storageMeter');if(m)m.innerHTML=storageMeterHtml();}
  if(n==='money'){const el=document.getElementById('moneyBody');if(el){let h='';try{h=bankrollSetHtml()+riskHtml()+missionsHtml()}catch(e){console.warn('missions',e)}try{h=msRoadmapSection()+h;}catch(e){}el.innerHTML=h+renderMoneyTab();}}
  if(n==='coach'){const el=document.getElementById('coachBody');if(el)el.innerHTML=renderCoachTab();}
  if(n==='today')renderToday();
  if(n==='banker')renderBankerTab();
  if(n==='grades')renderRecordsHub();
  if(n==='mine')openMyGames();
  window.scrollTo(0,0);
  tabRemember(n);
}
/* v2.00 · iOS drops a home-screen app from memory in the background, and the relaunch
   always opened on Games. The last tab + scroll are kept per page (device-only, never
   synced) and restored on a relaunch within 3 hours. Tapping a sport still opens its board. */
const LASTTAB_KEY='td.lastTab';
function tabRemember(n){try{localStorage.setItem(LASTTAB_KEY,JSON.stringify({n,p:location.pathname,ts:Date.now(),y:0}));}catch(e){}}
function tabRememberScroll(){try{const o=JSON.parse(localStorage.getItem(LASTTAB_KEY)||'null');if(!o||o.p!==location.pathname)return;o.y=Math.round(window.scrollY||0);o.ts=Date.now();localStorage.setItem(LASTTAB_KEY,JSON.stringify(o));}catch(e){}}
function tabForget(){try{localStorage.removeItem(LASTTAB_KEY);}catch(e){}}
function tabRestore(){try{const o=JSON.parse(localStorage.getItem(LASTTAB_KEY)||'null');
  if(!o||o.p!==location.pathname||!o.n||o.n==='games'||Date.now()-o.ts>3*3600e3||location.hash)return false;
  if(!document.getElementById('v-'+o.n))return false;
  const b=[...document.querySelectorAll('nav button')].find(x=>new RegExp("tab\\('"+o.n+"'").test(x.getAttribute('onclick')||''));
  tab(o.n,b||null);if(o.y)setTimeout(()=>window.scrollTo(0,o.y),400);return true;}catch(e){return false;}}
if(typeof window!=='undefined'){let _st=null;
  window.addEventListener('scroll',()=>{clearTimeout(_st);_st=setTimeout(tabRememberScroll,500);},{passive:true});
  document.addEventListener('visibilitychange',()=>{if(document.hidden)tabRememberScroll();});
  window.addEventListener('load',()=>setTimeout(tabRestore,700));}

/* ================= MATH ================= */
/* ══ DETERMINISTIC SIMS (v1.85) ════════════════════════════════════════════
   Every sim drew from Math.random, so a reload re-rolled 10,000 games and the
   win %, most-common score and any pick sitting near a threshold could flip.
   Now each sim runs on its own seeded stream (sport + game + sample size): the
   same inputs give the same numbers on every reload, every device. Numbers move
   only when an INPUT moves — a lineup, a line, a new grade in calibration. */
let _SIMR=null;
function simRand(){return _SIMR?_SIMR():Math.random();}
function simHash(s){let h=2166136261>>>0;s=String(s);for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)>>>0;}return h>>>0;}
let _SIMK='';
function simSeeded(fn,keyFn){if(!fn||fn.__seeded)return fn;const w=function(...a){const prev=_SIMR,prevK=_SIMK;let k='';try{k=String(keyFn.apply(this,a));}catch(e){}
  _SIMR=sjRng(simHash(k));_SIMK=k;try{return fn.apply(this,a);}finally{_SIMR=prev;_SIMK=prevK;}};w.__seeded=true;w.__raw=fn;return w;}
/* ══ SIM ONCE, REUSE EVERYWHERE (v1.85) ════════════════════════════════════
   The Monte Carlo loop is the only expensive part of a sim, and it depends on
   nothing but the model's inputs (projected scoring, spread of outcomes, sample
   size, the game's seed). Odds, calibration and every market read are applied
   AFTER it, from the stored histograms. So the loop runs once per game per set
   of inputs and the result is saved on the device: a reload reads it back in
   well under a millisecond instead of re-simming the slate. It re-runs only
   when an input actually moves (lineup, ratings, weather, learned drift). */
const SIMC_KEY='d4.simcore',SIMC_VER='s1';let SIMC=null,SIMC_DIRTY=0,SIMC_T=null;const SIMC_STATS={hit:0,miss:0,ms:0};
function simcStore(){if(!SIMC){try{const v=get(SIMC_KEY,{});SIMC=v&&typeof v==='object'?v:{};}catch(e){SIMC={};}}return SIMC;}
function simcFlush(){SIMC_T=null;if(!SIMC_DIRTY||!SIMC)return;SIMC_DIRTY=0;
  try{const lo=dayShift(today(),-4);Object.keys(SIMC).forEach(k=>{if(!SIMC[k]||String(SIMC[k].d)<lo)delete SIMC[k];});
    const ks=Object.keys(SIMC);if(ks.length>600)ks.sort((a,b)=>SIMC[a].ts-SIMC[b].ts).slice(0,ks.length-600).forEach(k=>delete SIMC[k]);
    set(SIMC_KEY,SIMC);}catch(e){}}
if(typeof window!=='undefined')window.addEventListener('pagehide',()=>{try{simcFlush()}catch(e){}});
function simCore(kind,inputs,run){
  const k=SIMC_VER+'|'+kind+'|'+_SIMK+'|'+inputs.map(x=>typeof x==='number'?(isFinite(x)?String(+x.toFixed(6)):String(x)):String(x)).join('|');
  const C=simcStore();const e=C[k];
  if(e&&e.v){SIMC_STATS.hit++;if(e.d!==today()){e.d=today();SIMC_DIRTY=1;if(!SIMC_T)SIMC_T=setTimeout(simcFlush,1500);}return e.v;}
  const t0=Date.now();const v=run();SIMC_STATS.miss++;SIMC_STATS.ms+=Date.now()-t0;
  C[k]={v,d:today(),ts:Date.now()};SIMC_DIRTY=1;if(!SIMC_T)SIMC_T=setTimeout(simcFlush,1500);return v;}
function simGameKey(sp,g,N){return sp+'|'+(g&&(g.id||((g.away&&g.away.abbr)+'@'+(g.home&&g.home.abbr))))+'|'+(N||'');}
function poisCDF(k,l){let s=0,t=Math.exp(-l);for(let i=0;i<=k;i++){s+=t;t*=l/(i+1)}return Math.min(1,s)}
function poisAtLeast(k,l){return k<=0?1:1-poisCDF(k-1,l)}
function poisSample(l){if(l<=0)return 0;
  if(l>25){const u=simRand()||1e-9,v=simRand();
    return Math.max(0,Math.round(l+Math.sqrt(l)*Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v)))}
  let L=Math.exp(-l),k=0,p=1;do{k++;p*=simRand()}while(p>L);return k-1}
// Was truncating k=3.6 to a full 4 exponential draws (for-loop with i<k runs i=0..3,
// silently drawing Gamma(4,θ) instead of Gamma(3.6,θ)). That widened variance and
// pushed the modal exact-score up a notch across nearly every game — part of why
// 3-4/4-3 kept winning "most common score" regardless of which teams were playing.
// Fixed with the standard integer-part-plus-fractional-remainder construction.
function gammaInt(k,t){
  const ik=Math.floor(k),frac=k-ik;
  let s=0;
  for(let i=0;i<ik;i++)s+=-Math.log(simRand()||1e-9);
  if(frac>1e-9){
    // Johnk's algorithm for the Gamma(frac,1) remainder, frac in (0,1)
    let x,y,u,v;
    do{
      u=simRand()||1e-9;v=simRand()||1e-9;
      x=Math.pow(u,1/frac);y=Math.pow(v,1/(1-frac));
    }while(x+y>1);
    const e=-Math.log(simRand()||1e-9);
    s+=(x/(x+y))*e;
  }
  return s*t;
}
function nbRuns(m){const k=hotGet(LS.calib,{}).dispK||3.6;return poisSample(gammaInt(k,Math.max(.15,m)/k))}
function tbDist(pv,n){let d=[1];for(let i=0;i<n;i++){const nd=new Array(d.length+4).fill(0);
  for(let a=0;a<d.length;a++)for(let b=0;b<5;b++)nd[a+b]+=d[a]*pv[b];d=nd}return d}
function atLeast(d,k){let s=0;for(let i=k;i<d.length;i++)s+=d[i];return Math.min(1,Math.max(0,s))}
function blendPA(f,pa){const lo=Math.floor(pa),w=pa-lo;return f(lo)*(1-w)+f(lo+1)*w}
function comb(n,k){if(k>n)return 0;let r=1;for(let i=0;i<k;i++)r=r*(n-i)/(i+1);return r}
function imp(a){return a>0?100/(a+100):(-a)/((-a)+100)}
/* ================= USAGE TRACKING ================= */
// Every metered source gets a call counted here, whether it succeeded or not — the goal
// is knowing how close to a real limit you are, not just celebrating successes.
function usage(){
  const d=get(LS.usage,{});
  const dayKey=today(),monthKey=today().slice(0,7);
  if(d.dayKey!==dayKey){d.odds_d=0;d.sharp_d=0;d.rundown_d=0;d.oddspapi_d=0;d.dayKey=dayKey}
  if(d.monthKey!==monthKey){d.oddspapi_m=0;d.monthKey=monthKey}
  return d;
}
function trackCall(platform){
  const d=usage();
  d[platform+'_d']=(d[platform+'_d']||0)+1;
  if(platform==='oddspapi')d.oddspapi_m=(d.oddspapi_m||0)+1;
  set(LS.usage,d);
}
function usageBar(label,used,limit,note){
  const pct=limit?Math.min(100,(used/limit)*100):0;
  const col=pct>=90?'var(--rust)':pct>=65?'var(--gold)':'var(--win)';
  return `<div style="margin-bottom:12px">
    <div style="display:flex;justify-content:space-between;font-family:'IBM Plex Mono';font-size:10.5px;margin-bottom:4px">
      <span>${label}</span><span style="color:var(--mute)">${limit?used+' / '+limit:used+' calls today — no confirmed limit'}</span>
    </div>
    <div style="height:6px;background:var(--panel2);border-radius:3px;overflow:hidden">
      <div style="height:100%;width:${limit?pct:Math.min(100,used*3)}%;background:${col};border-radius:3px"></div>
    </div>
    ${note?`<div style="font-family:'IBM Plex Mono';font-size:9px;color:var(--mute);margin-top:3px">${note}</div>`:''}
  </div>`;
}
