  if(r.hit===true)return'<span class="pp" style="color:var(--win)">100%</span>';
  if(r.hit===false)return'<span class="pp" style="color:var(--rust)">0%</span>';
  if(r.push)return'<span class="pp" style="color:var(--mute)">PUSH</span>';
