      let kp=null;if(hasLine){kp=imp(price);if(c.other&&c.other.price!=null){const k2=imp(+c.other.price);kp=kp/(kp+k2);}}
      const mp=typeof c.p==='number'&&isFinite(c.p)?c.p:null;
